import re
from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
from ta_moler.cmd.btssm.genericbtssm import Genericbtssm


class Collectsnapshot(Genericbtssm):
    """Collectsnapshot command class."""

    def __init__(self, ne, pw, java_version, snapshot_file, connection, prompt=None, newline_chars=None, runner=None):
        """
        Collectsnapshot command.

        :param ne: single IP address of one site.
        :param pw: sets of credentials for the sites.
        :param java_version: Java version used to create path structure.
        :param snapshot_file: Full path with filename for snapshot file.
        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: Prompt of the starting shell.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        """
        super(Collectsnapshot, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ne = ne
        self.pw = pw
        self.java_version = java_version
        self.snapshot_file = snapshot_file

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"./jre/{self.java_version}/bin/java -Djava.awt.headless=true -classpath ./cl/cl.jar -client " \
              f"com.nokia.em.poseidon.PoseidonStarter -confFile ./cl/CLConf.xml -logcoverage all " \
              f"-ne {self.ne} -pw {self.pw} -snapshotfilename {self.snapshot_file} -savesnapshot"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise.
        :return: None
        """
        if is_full_line:
            try:
                self._parse_saved_successfully(line)
                self._parse_failed_to_save(line)
            except ParsingDone:
                pass
        return super(Collectsnapshot, self).on_new_line(line, is_full_line)

    # Snapshot saved successfully
    _re_saved_successfully = re.compile(r"(?P<SUCCESS>Snapshot\s+saved\s+successfully)", re.I)

    def _parse_saved_successfully(self, line):
        if self._regex_helper.search_compiled(Collectsnapshot._re_saved_successfully, line):
            self.current_ret["RESULT"] = "SUCCESS"
            raise ParsingDone

    # Failed to save snapshot
    _re_failed_to_save = re.compile(r"(?P<FAILED>Failed\s+to\s+save\s+snapshot)", re.I)

    def _parse_failed_to_save(self, line):
        if self._regex_helper.search_compiled(Collectsnapshot._re_failed_to_save, line):
            self.current_ret["RESULT"] = "FAILED"
            self.set_exception(CommandFailure(self, self._regex_helper.group("FAILED")))
            raise ParsingDone


